it.effect.each([{ nativeModel: "composer-2.5" }, { nativeModel: undefined }])("validates legacy SDK metadata with model $nativeModel without a prompt", ({ nativeModel }) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const cwd = yield* fs.makeTempDirectoryScoped({ prefix: "cursor-legacy-metadata-" });
    const instanceId = ProviderInstanceId.make("cursor");
    const threadId = ThreadId.make("cursor-legacy-thread");
    const providerSessionId = ProviderSessionId.make("cursor-legacy-session");
    const modelSelection = { instanceId, model: "composer-2.5" };
    const runtimePolicy = ProviderAdapter.ProviderAdapterV2RuntimePolicy.make({ cwd, runtimeMode: "approval-required", interactionMode: "default" });
    let sends = 0;
    const opened: string[] = [];
    const sdkSession: CursorAgentSdk.CursorAgentSdkSession = {
      agentId: "stored-local-agent", listMessages: Effect.succeed([]), close: Effect.void,
      send: () => { sends++; return Effect.die("Metadata adoption must not send."); },
    };
    const metadata = {
      agentId: "stored-local-agent", runtime: "local" as const, cwd, homeDirectory: cwd,
      runs: [{ id: "stored-error-run", status: "error" }, { id: "stored-cancelled-run", status: "cancelled" },
        { id: "stored-completed-run", status: "finished", ...(nativeModel ? { model: nativeModel } : {}) }],
    };
    bindCursorNativeMetadata(sdkSession, Effect.sync(() => metadata));
    const adapter = yield* makeCursorAdapterV2({ instanceId, environment: { HOME: cwd } }).pipe(
      Effect.provideService(CursorAgentSdk.CursorAgentSdkRunner, { assertComplete: Effect.void,
        open: input => Effect.sync(() => { opened.push(input.operation); return sdkSession; }) }),
      Effect.provide(TestProviderHost.layer({ cwd })),
    );
    const runtime = yield* adapter.openSession({ threadId, providerSessionId, modelSelection, runtimePolicy, initialNativeThreadId: "stored-local-agent" });
    const evidence = readCursorSessionEvidence(runtime)!;
    assert.equal((yield* evidence.probe).cwd, cwd);
    const ensure = { threadId, providerSessionId, modelSelection, runtimePolicy };
    const snapshot = yield* evidence.readLegacy({ nativeSessionId: "stored-local-agent", turnId: "stored-completed-run", ensure });
    assert.equal(snapshot.providerThread.nativeThreadRef?.nativeId, "stored-local-agent");
    assert.deepEqual(snapshot.providerTurns, []);
    assert.deepEqual(snapshot.nativeHistory, { nativeSessionId: "stored-local-agent",
      completedTurnRefs: [{ driver: CursorAgentSdk.CURSOR_PROVIDER, nativeId: "stored-completed-run", strength: "strong" }] });
    assert.equal(snapshot.providerThread.nativeMetadata?.modelSelection?.model, nativeModel);
    assert.equal((yield* evidence.readLegacy({ nativeSessionId: "foreign-agent", ensure }).pipe(Effect.result))._tag, "Failure");
    assert.equal((yield* evidence.readLegacy({ nativeSessionId: "stored-local-agent", turnId: "missing-run", ensure }).pipe(Effect.result))._tag, "Failure");
    for (const turnId of ["stored-error-run", "stored-cancelled-run"]) {
      assert.equal((yield* evidence.readLegacy({ nativeSessionId: "stored-local-agent", turnId, ensure }).pipe(Effect.result))._tag, "Failure");
    }
    metadata.runs.unshift({ id: "newer-completed-run", status: "finished", model: "different-native-model" });
    const refreshed = yield* evidence.readLegacy({ nativeSessionId: "stored-local-agent", turnId: "stored-completed-run", ensure });
    assert.equal(refreshed.nativeHistory?.completedTurnRefs.length, 2);
    assert.equal(refreshed.providerThread.nativeMetadata?.modelSelection?.model, nativeModel);
    const direct = yield* runtime.readThreadSnapshot({ providerThread: refreshed.providerThread });
    assert.deepEqual(direct.nativeHistory, refreshed.nativeHistory);
    metadata.homeDirectory = "/foreign-native-home";
    assert.equal((yield* evidence.probe.pipe(Effect.result))._tag, "Failure");
    metadata.homeDirectory = cwd;
    metadata.cwd = "/foreign-native-workspace";
    assert.equal((yield* runtime.readThreadSnapshot({ providerThread: refreshed.providerThread }).pipe(Effect.result))._tag, "Failure");
    metadata.cwd = cwd;
    const beforeForeign = opened.length;
    assert.equal((yield* runtime.readThreadSnapshot({ providerThread: {
      ...refreshed.providerThread, providerInstanceId: ProviderInstanceId.make("foreign-instance"),
    } }).pipe(Effect.result))._tag, "Failure");
    assert.equal(opened.length, beforeForeign);
    assert.deepEqual(opened, ["resume"]);
    assert.equal(sends, 0);
  }).pipe(Effect.scoped, Effect.provide(Layer.mergeAll(NodeServices.layer, IdAllocator.layer, RuntimeHost.layer))),
);
it.effect.each(["close", "assertComplete"] as const)("fails the owning scope on Cursor %s cleanup failure", failing =>
  Effect.gen(function* () {
    const calls: string[] = [];
    const error = new CursorAgentSdk.CursorAgentSdkRunnerError({ method: failing, cause: new Error("cleanup failed") });
    const outcome = yield* Effect.gen(function* () {
      const adapter = yield* makeCursorAdapterV2({
        instanceId: ProviderInstanceId.make("cursor-cleanup"), environment: {},
      }).pipe(Effect.provideService(CursorAgentSdk.CursorAgentSdkRunner, {
        assertComplete: Effect.sync(() => calls.push("assertComplete")).pipe(
          Effect.andThen(failing === "assertComplete" ? Effect.fail(error) : Effect.void)),
        open: () => Effect.succeed({
          agentId: "cleanup-agent", listMessages: Effect.succeed([]),
          send: () => Effect.die("Cleanup must not send a prompt."),
          close: Effect.sync(() => calls.push("close")).pipe(
            Effect.andThen(failing === "close" ? Effect.fail(error) : Effect.void)),
        }),
      }));
      const instanceId = ProviderInstanceId.make("cursor-cleanup");
      const policy = ProviderAdapter.ProviderAdapterV2RuntimePolicy.make({ cwd: "/workspace",
        runtimeMode: "approval-required", interactionMode: "default" });
      const runtime = yield* adapter.openSession({ threadId: ThreadId.make("cleanup-thread"),
        providerSessionId: ProviderSessionId.make("cleanup-session"),
        modelSelection: { instanceId, model: "composer-2.5" }, runtimePolicy: policy });
      yield* runtime.ensureThread({ threadId: ThreadId.make("cleanup-thread"),
        modelSelection: { instanceId, model: "composer-2.5" }, runtimePolicy: policy });
    }).pipe(Effect.scoped, Effect.exit);
    assert.isTrue(Exit.isFailure(outcome));
    assert.deepEqual(calls, ["close", "assertComplete"]);
  }).pipe(Effect.provide(TestProviderHost.layer({ cwd: "/workspace" })),
    Effect.provide(Layer.mergeAll(NodeServices.layer, IdAllocator.layer, RuntimeHost.layer))),
);

